//! Signing vectors generated by the official Python SDK (`tests/vectors.json`).

use roshar_hyperliquid::Signer;
use roshar_hyperliquid::{Action, Cloid, OrderRef, OrderReq, Tif};
use serde_json::Value;

fn load() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn cloid(s: &str) -> Cloid {
    hex::decode(s.trim_start_matches("0x"))
        .unwrap()
        .try_into()
        .unwrap()
}

fn order(o: &Value) -> OrderReq {
    let tif = match o["t"]["limit"]["tif"].as_str().unwrap() {
        "Alo" => Tif::Alo,
        "Ioc" => Tif::Ioc,
        "Gtc" => Tif::Gtc,
        t => panic!("tif {t}"),
    };
    OrderReq {
        asset: o["a"].as_u64().unwrap() as u32,
        is_buy: o["b"].as_bool().unwrap(),
        px: o["p"].as_str().unwrap().parse().unwrap(),
        sz: o["s"].as_str().unwrap().parse().unwrap(),
        reduce_only: o["r"].as_bool().unwrap(),
        tif,
        cloid: o.get("c").map(|c| cloid(c.as_str().unwrap())),
    }
}

fn action(a: &Value) -> Action {
    let fast = a.get("f").and_then(Value::as_bool).unwrap_or(false);
    match a["type"].as_str().unwrap() {
        "order" => Action::Order {
            orders: a["orders"].as_array().unwrap().iter().map(order).collect(),
            priority: a["grouping"].get("p").map(|p| p.as_u64().unwrap()),
        },
        "batchModify" => Action::BatchModify {
            modifies: a["modifies"]
                .as_array()
                .unwrap()
                .iter()
                .map(|m| {
                    let r = match &m["oid"] {
                        Value::String(s) => OrderRef::Cloid(cloid(s)),
                        n => OrderRef::Oid(n.as_u64().unwrap()),
                    };
                    (r, order(&m["order"]))
                })
                .collect(),
        },
        "modify" => Action::Modify {
            oid: match &a["oid"] {
                Value::String(s) => OrderRef::Cloid(cloid(s)),
                n => OrderRef::Oid(n.as_u64().unwrap()),
            },
            order: order(&a["order"]),
            always_place: a.get("a").and_then(Value::as_bool).unwrap_or(false),
        },
        "cancel" => Action::Cancel {
            cancels: a["cancels"]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| (c["a"].as_u64().unwrap() as u32, c["o"].as_u64().unwrap()))
                .collect(),
            fast,
        },
        "cancelByCloid" => Action::CancelByCloid {
            cancels: a["cancels"]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| {
                    (
                        c["asset"].as_u64().unwrap() as u32,
                        cloid(c["cloid"].as_str().unwrap()),
                    )
                })
                .collect(),
            fast,
        },
        t => panic!("type {t}"),
    }
}

/// Hex big-endian integer, compared without leading zeros.
fn int_hex(s: &str) -> String {
    let t = s
        .trim_start_matches("0x")
        .trim_start_matches('0')
        .to_ascii_lowercase();
    if t.is_empty() {
        "0".into()
    } else {
        t
    }
}

#[test]
fn sdk_vectors() {
    let v = load();
    let key = v["key"].as_str().unwrap();
    let mainnet = v.get("mainnet").and_then(Value::as_bool).unwrap_or(true);
    let cases = v["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 12);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let signer = Signer::from_hex(key, c["vault"].as_str(), mainnet).unwrap();
        let act = action(&c["action"]);
        let nonce = c["nonce"].as_u64().unwrap();

        assert_eq!(
            Signer::action_json(&act),
            c["action"],
            "{name}: action json"
        );
        let cid = signer.connection_id(&act, nonce).unwrap();
        assert_eq!(
            format!("0x{}", hex::encode(cid)),
            c["connection_id"].as_str().unwrap(),
            "{name}: connection id"
        );

        let p = signer.sign(&act, nonce).unwrap();
        let (sig, want) = (&p["signature"], &c["signature"]);
        assert_eq!(
            int_hex(sig["r"].as_str().unwrap()),
            int_hex(want["r"].as_str().unwrap()),
            "{name}: r"
        );
        assert_eq!(
            int_hex(sig["s"].as_str().unwrap()),
            int_hex(want["s"].as_str().unwrap()),
            "{name}: s"
        );
        assert_eq!(sig["v"], want["v"], "{name}: v");
        assert_eq!(p["action"], c["action"], "{name}: payload action");
        assert_eq!(p["nonce"].as_u64(), Some(nonce));
        assert_eq!(p["vaultAddress"], c["vault"], "{name}: vaultAddress");
    }
}

#[test]
fn signer_address_matches_vectors() {
    let v = load();
    if let Some(addr) = v.get("address").and_then(Value::as_str) {
        let s = Signer::from_hex(v["key"].as_str().unwrap(), None, true).unwrap();
        assert_eq!(s.address(), addr.to_ascii_lowercase());
    }
}

/// `cargo test --release -p roshar-hyperliquid --test vectors -- --ignored --nocapture bench_sign`
#[test]
#[ignore]
fn bench_sign() {
    let v = load();
    let c = &v["cases"][0];
    let signer = Signer::from_hex(v["key"].as_str().unwrap(), c["vault"].as_str(), true).unwrap();
    let act = action(&c["action"]);
    let mut ns = Vec::with_capacity(1000);
    for i in 0..1100u64 {
        let t = std::time::Instant::now();
        let p = signer.sign(&act, 1_793_200_000_000 + i).unwrap();
        let dt = t.elapsed().as_nanos() as u64;
        std::hint::black_box(p);
        if i >= 100 {
            ns.push(dt);
        }
    }
    ns.sort_unstable();
    println!(
        "Signer::sign over {} iters: p50 {} us, p90 {} us, p99 {} us",
        ns.len(),
        ns[ns.len() / 2] / 1000,
        ns[ns.len() * 9 / 10] / 1000,
        ns[ns.len() * 99 / 100] / 1000
    );
}
